rows = [[5]*24 for _ in range(7)]
markers = {0:[7,8,9,10,18],1:[2,8,9,15,19,20],2:[8,14,20,21,24],3:[3,5,6,8],4:[3,5,10,21,24],5:[8,9,10,13,15],6:[1,3,5,12,21]}
for r,cs in markers.items():
    for c in cs: rows[r][c-1]=2
for r in range(7):
    cs=[c for c in range(24) if rows[r][c]==2]
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b): rows[r][c]=3
for c in range(24):
    rs=[r for r in range(7) if rows[r][c]==2]
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b): rows[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in rows))
